package com.ute.uteexpress.operations;

import com.ute.uteexpress.dto.operations.CustomerTicketCommands;
import com.ute.uteexpress.dto.operations.TicketCommands;
import com.ute.uteexpress.entity.*;
import com.ute.uteexpress.enums.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import com.ute.uteexpress.service.notifications.NotificationDelivery;
import static com.ute.uteexpress.operations.OperationsJdbcFixture.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real H2 JDBC transactions/row locks, not a mock concurrency model or SQL Server verification. */
@SpringJUnitConfig(OperationsJdbcConfig.class)
class CustomerSupportConcurrencyTests extends CustomerSupportJdbcSupport {
    @Autowired NotificationDelivery delivery;
    @Autowired java.util.List<org.springframework.messaging.Message<?>> socketSignals;
    <T>T user(Callable<T> action)throws Exception {as(f.owner,"ROLE_USER");try{return action.call();}finally{SecurityContextHolder.clearContext();}}
    void pair(Callable<?> a,Callable<?> b)throws Exception {
        var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);
        try{var first=pool.submit(()->{start.await();return a.call();});var second=pool.submit(()->{start.await();return b.call();});start.countDown();first.get(10,TimeUnit.SECONDS);second.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}
    }
    boolean attempt(User actor,String role,Runnable action){as(actor,role);try{action.run();return true;}catch(ObjectOptimisticLockingFailureException expected){return false;}finally{SecurityContextHolder.clearContext();}}
    void oneWinner(Callable<Boolean> a,Callable<Boolean> b)throws Exception{var result=new CopyOnWriteArrayList<Boolean>();pair(()->{result.add(a.call());return null;},()->{result.add(b.call());return null;});assertEquals(1,result.stream().filter(Boolean::booleanValue).count());}
    @Test void twoConcurrentCreatePostsWithSameTokenReturnOneTicket()throws Exception{var c=createCommand();var ids=new CopyOnWriteArrayList<Long>();pair(()->user(()->{ids.add(tickets.createCustomer(c));return null;}),()->user(()->{ids.add(tickets.createCustomer(c));return null;}));assertEquals(2,ids.size());assertEquals(ids.get(0),ids.get(1));assertEquals(1,ticketRows.count());assertEquals(1,eventRows.count());}
    @Test void sameMessageRetryRacingCreatesOneMessageAndOneAudit()throws Exception{Long id=createCustomer();var c=message(id,"Same request");pair(()->user(()->{tickets.customerMessage(id,c);return null;}),()->user(()->{tickets.customerMessage(id,c);return null;}));assertEquals(1,messageRows.count());assertEquals(2,eventRows.count());}
    @Test void twoDifferentMessagesWithSameVersionHaveOneWinner()throws Exception{Long id=createCustomer();var a=message(id,"First");var b=message(id,"Second");oneWinner(()->attempt(f.owner,"ROLE_USER",()->tickets.customerMessage(id,a)),()->attempt(f.owner,"ROLE_USER",()->tickets.customerMessage(id,b)));assertEquals(1,messageRows.count());assertEquals(2,eventRows.count());}
    @Test void customerMessageRacingManagerReplyDoesNotSilentlyOverwrite()throws Exception{Long id=createCustomer(),v=version(id);var c=message(id,"Customer");oneWinner(()->attempt(f.owner,"ROLE_USER",()->tickets.customerMessage(id,c)),()->attempt(f.manager,"ROLE_MANAGER",()->tickets.reply(id,new TicketCommands.Message(v,"Manager"))));assertEquals(1,messageRows.count());assertEquals(2,eventRows.count());}
    @Test void resolutionRacingCustomerMessageHasOneVersionWinner()throws Exception{Long id=createCustomer();state(id,TicketStatus.PROCESSING);Long v=version(id);var c=message(id,"Evidence");long count=eventRows.count();oneWinner(()->attempt(f.owner,"ROLE_USER",()->tickets.customerMessage(id,c)),()->attempt(f.manager,"ROLE_MANAGER",()->tickets.resolve(id,new TicketCommands.Decision(v,"Resolution"))));assertEquals(count+1,eventRows.count());assertEquals(1,messageRows.count());}
    @Test void closedTicketCannotAcceptPostFromAnOldOpenForm(){Long id=createCustomer();var old=message(id,"Outdated form");state(id,TicketStatus.CLOSED);assertThrows(ObjectOptimisticLockingFailureException.class,()->tickets.customerMessage(id,old));assertEquals(1,messageRows.count());assertEquals(TicketStatus.CLOSED,ticketRows.findById(id).orElseThrow().getStatus());}
    @Test void closeRacingReopenRequestLeavesOneConsistentResult()throws Exception{Long id=createCustomer();state(id,TicketStatus.RESOLVED);Long v=version(id);var c=message(id,"Please review");long before=eventRows.count();oneWinner(()->attempt(f.owner,"ROLE_USER",()->tickets.requestCustomerReopen(id,c)),()->attempt(f.manager,"ROLE_MANAGER",()->tickets.close(id,new TicketCommands.Decision(v,"Verified"))));assertEquals(before+1,eventRows.count());assertTrue(Set.of(TicketStatus.RESOLVED,TicketStatus.CLOSED).contains(ticketRows.findById(id).orElseThrow().getStatus()));}
    @Test void managerReopenRacingCustomerRequestDoesNotLoseAudit()throws Exception{Long id=createCustomer();state(id,TicketStatus.CLOSED);Long v=version(id);var c=message(id,"Review request");long before=eventRows.count();oneWinner(()->attempt(f.owner,"ROLE_USER",()->tickets.requestCustomerReopen(id,c)),()->attempt(f.manager,"ROLE_MANAGER",()->tickets.reopen(id,new TicketCommands.Decision(v,"Accepted"))));assertEquals(before+1,eventRows.count());}
    @Test void duplicateReopenRequestRacingCreatesOneRequest()throws Exception{Long id=createCustomer();state(id,TicketStatus.CLOSED);var c=message(id,"Review");pair(()->user(()->{tickets.requestCustomerReopen(id,c);return null;}),()->user(()->{tickets.requestCustomerReopen(id,c);return null;}));assertEquals(1,eventRows.pendingReopenRequests(id));assertEquals(2,messageRows.count());}
    @Test void outerCreateRollbackLeavesNoTicketOutboxOrNotification(){var c=createCommand();assertThrows(IllegalStateException.class,()->db(()->{tickets.createCustomer(c);assertEquals(0,notices.count());throw new IllegalStateException("Synthetic rollback");}));assertEquals(0,ticketRows.count());assertEquals(0,eventRows.count());assertEquals(0,notices.count());}
    @Test void outerMessageRollbackLeavesNoMessageEventOrVersionChange(){Long id=createCustomer(),v=version(id);var c=message(id,"Rollback text");assertThrows(IllegalStateException.class,()->db(()->{tickets.customerMessage(id,c);throw new IllegalStateException("Synthetic rollback");}));assertEquals(0,messageRows.count());assertEquals(1,eventRows.count());assertEquals(v,version(id));assertEquals(0,notices.count());tickets.customerMessage(id,c);assertEquals(1,messageRows.count());}
    @Test void actualAuditConstraintFailureRollsBackCustomerMessageAndRoot(){Long id=createCustomer(),v=version(id);db(()->{em.createNativeQuery("ALTER TABLE dbo.support_ticket_events ADD CONSTRAINT test_reject_customer CHECK (action <> 'CUSTOMER_MESSAGE')").executeUpdate();return null;});try{assertThrows(RuntimeException.class,()->tickets.customerMessage(id,message(id,"Rollback")));assertEquals(0,messageRows.count());assertEquals(1,eventRows.count());assertEquals(v,version(id));}finally{db(()->{em.createNativeQuery("ALTER TABLE dbo.support_ticket_events DROP CONSTRAINT test_reject_customer").executeUpdate();return null;});}}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"LOCKED","ROLE_REVOKED"})
    void accountDisabledWhileWriterWaitsForTicketLockIsRechecked(String change)throws Exception{
        Long id=createCustomer();var c=message(id,"Must not commit");var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var started=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
        try{var holder=pool.submit(()->db(()->{em.find(SupportTicket.class,id,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);locked.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}if(change.equals("LOCKED"))em.find(User.class,f.owner.getId()).setStatus(UserStatus.LOCKED);else em.createQuery("delete from UserRole r where r.user.id=:id").setParameter("id",f.owner.getId()).executeUpdate();return true;}));assertTrue(locked.await(3,TimeUnit.SECONDS));var writer=pool.submit(()->user(()->{started.countDown();tickets.customerMessage(id,c);return true;}));assertTrue(started.await(3,TimeUnit.SECONDS));Thread.sleep(100);assertFalse(writer.isDone());release.countDown();holder.get(6,TimeUnit.SECONDS);var failure=assertThrows(ExecutionException.class,()->writer.get(6,TimeUnit.SECONDS));assertTrue(failure.getCause() instanceof AccessDeniedException || (failure.getCause() instanceof org.springframework.web.server.ResponseStatusException denied && denied.getStatusCode().value()==404));assertEquals(0,messageRows.count());assertEquals(1,eventRows.count());}finally{release.countDown();pool.shutdownNow();}
    }
    @Test void branchChangeAndVersionAdvanceWhileWriterWaitsIsConflict()throws Exception{
        Long id=createCustomer();var c=message(id,"Stale branch");var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var started=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
        try{var holder=pool.submit(()->db(()->{var t=em.find(SupportTicket.class,id,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);locked.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}t.setHandlingBranch(em.find(Branch.class,f.destination.getId()));return true;}));assertTrue(locked.await(3,TimeUnit.SECONDS));var writer=pool.submit(()->user(()->{started.countDown();tickets.customerMessage(id,c);return true;}));assertTrue(started.await(3,TimeUnit.SECONDS));Thread.sleep(100);assertFalse(writer.isDone());release.countDown();holder.get(6,TimeUnit.SECONDS);var failure=assertThrows(ExecutionException.class,()->writer.get(6,TimeUnit.SECONDS));assertInstanceOf(ObjectOptimisticLockingFailureException.class,failure.getCause());assertEquals(0,messageRows.count());}finally{release.countDown();pool.shutdownNow();}
    }
    @Test void concurrentWorkersDeduplicateCustomerCreateRecipientsAtomically()throws Exception{Long id=createCustomer(),source=event(id,TicketAction.CREATED);pair(()->{notifications.process(source);return null;},()->{notifications.process(source);return null;});assertEquals(2,notices.count());assertNotNull(eventRows.findById(source).orElseThrow().getProcessedAt());}
    @Test void notificationFailureRollsBackAllRecipientsThenPersistedRetryRecovers(){Long id=createCustomer(),source=event(id,TicketAction.CREATED);db(()->{em.createNativeQuery("ALTER TABLE dbo.notifications ADD CONSTRAINT test_reject_customer_notice CHECK (user_id <> "+f.secondManager.getId()+")").executeUpdate();return null;});try{assertThrows(RuntimeException.class,()->notifications.process(source));assertEquals(0,notices.count());assertNull(eventRows.findById(source).orElseThrow().getProcessedAt());notifications.retry(source);assertNotNull(eventRows.findById(source).orElseThrow().getRetryAt());}finally{db(()->{em.createNativeQuery("ALTER TABLE dbo.notifications DROP CONSTRAINT test_reject_customer_notice").executeUpdate();return null;});}clock.set(NOW.plusSeconds(3));notifications.process(source);notifications.process(source);assertEquals(2,notices.count());}
    @Test void deliveryUsesExistingPrivateRefreshWithoutTicketOrMessagePayload(){Long id=createCustomer();as(f.manager,"ROLE_MANAGER");tickets.reply(id,new TicketCommands.Message(version(id),"BODY MUST STAY PRIVATE"));notifications.process(event(id,TicketAction.PUBLIC_REPLY));socketSignals.clear();delivery.deliver(notices.findAll().getFirst().getId());assertEquals(1,socketSignals.size());var signal=socketSignals.getFirst();assertEquals(Map.of("type","REFRESH"),signal.getPayload());assertFalse(signal.toString().contains("BODY MUST STAY PRIVATE"));assertTrue(signal.getHeaders().get("simpDestination").toString().contains("/queue/notifications"));}
}
